'use strict';

// packages/recommendation-core/test/characterization.test.js — protection L2:
// the extracted implementation must reproduce the outputs the ORIGINAL
// implementation produced, field for field.
//
// The fixture (test/fixtures/pr2-characterization.json) was generated by
// scripts/characterize-pr2.js from src/recommendation/** before any module
// moved here, and its provenance block names that commit. The inputs below are
// read back out of the fixture and replayed against the extracted code, so the
// expected values were never produced by the implementation under test.
//
// A difference here is an unexplained behaviour change, not a stale fixture:
// do not regenerate the file to make this pass.

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');

const core = require('..');
const fixture = require('./fixtures/pr2-characterization.json');

const { createCandidateSelectionInput, createCandidate, selectCandidatePool } = core.candidates;
const { filterCandidates } = core.filtering;
const { buildIntegratedGpuPresentMap } = core.filtering;

function capturedError(fn) {
  try {
    fn();
  } catch (err) {
    return {
      name: err.name,
      code: err.code === undefined ? null : err.code,
      field: err.field === undefined ? null : err.field,
      message: err.message,
    };
  }
  throw new Error('expected the call to throw, but it returned');
}

describe('characterization: candidates', () => {
  it('validates the selection input identically', () => {
    const { input, validated } = fixture.candidates.selection_input;
    assert.deepEqual(createCandidateSelectionInput(input), validated);
  });

  it('rejects the invalid selection input identically', () => {
    const { input, error } = fixture.candidates.selection_input_rejection;
    assert.deepEqual(capturedError(() => createCandidateSelectionInput(input)), error);
  });

  it('builds candidates identically (product-keyed and variant-keyed)', () => {
    assert.deepEqual(
      createCandidate({
        component_role: 'CPU',
        category: 'CPU',
        product_id: fixture.candidates.candidate_base.product_id,
      }),
      fixture.candidates.candidate_base
    );
    assert.deepEqual(
      createCandidate({
        component_role: 'GPU',
        category: 'GPU',
        product_id: fixture.candidates.candidate_variant.product_id,
        product_variant_id: fixture.candidates.candidate_variant.product_variant_id,
      }),
      fixture.candidates.candidate_variant
    );
  });

  it('rejects the invalid candidate identically', () => {
    const { input, error } = fixture.candidates.candidate_rejection;
    assert.deepEqual(capturedError(() => createCandidate(input)), error);
  });

  it('selects the pool identically, in the same canonical order', () => {
    const { input, output } = fixture.candidates.pool;
    const actual = selectCandidatePool(input.selection_input, input.candidates);
    assert.deepEqual(actual, output);
  });

  it('still produces a deterministic pool', () => {
    const { input, output } = fixture.candidates.pool;
    const again = selectCandidatePool(input.selection_input, input.candidates);
    assert.deepEqual(again, output);
    assert.equal(JSON.stringify(again), JSON.stringify(output));
  });

  it('rejects an empty pool identically', () => {
    const { input, error } = fixture.candidates.pool_empty_rejection;
    assert.deepEqual(
      capturedError(() => selectCandidatePool(input.selection_input, input.candidates)),
      error
    );
  });
});

describe('characterization: filtering', () => {
  for (const entry of fixture.filtering) {
    it('reproduces the frozen verdicts for ' + entry.name, () => {
      assert.deepEqual(filterCandidates(entry.context), entry.output);
    });
  }

  it('covers every candidate verdict, so a PASS-only regression cannot hide', () => {
    const statuses = new Set();
    for (const entry of fixture.filtering) {
      for (const result of entry.output.results) statuses.add(result.status);
    }
    assert.deepEqual([...statuses].sort(), ['PASS', 'REJECT', 'UNKNOWN']);
  });
});

describe('characterization: integrated-GPU handoff', () => {
  for (const entry of fixture.igpu_map) {
    it('reproduces the frozen map for ' + entry.name, () => {
      assert.deepEqual(buildIntegratedGpuPresentMap(entry.context), entry.output);
    });
  }

  it('still distinguishes true, false and null rather than collapsing them', () => {
    const values = new Set();
    for (const entry of fixture.igpu_map) {
      for (const value of Object.values(entry.output)) values.add(String(value));
    }
    assert.deepEqual([...values].sort(), ['false', 'null', 'true']);
  });
});

describe('characterization: provenance', () => {
  it('names the pre-move baseline rather than the extracted commit', () => {
    assert.match(fixture.provenance.baseline_sha, /^[0-9a-f]{40}$/);
    assert.equal(fixture.provenance.command, 'node scripts/characterize-pr2.js');
    assert.match(fixture.provenance.origin, /PRE-MOVE/);
  });
});
